<?php use Simit\Core\Csrf; $me=(int)Simit\Core\Auth::user()['id']; ?>
<div class="chat-shell"><aside class="panel chat-contacts"><div class="chat-title"><h2>Chat</h2><p><?=__('Pilih akun untuk memulai percakapan.','Choose an account to start a conversation.')?></p></div><?php foreach($contacts as $contact):?><a href="/chat?user=<?=$contact['id']?>" class="contact <?=($peer['id']??0)==$contact['id']?'active':''?>"><span class="avatar"><?=e(strtoupper(substr($contact['name'],0,1)))?></span><div><strong><?=e($contact['name'])?></strong><small><?=e(ucfirst($contact['role']))?></small></div><?php if($contact['unread']):?><b class="count-badge"><?=$contact['unread']?></b><?php endif;?></a><?php endforeach;?></aside><section class="panel chat-room"><?php if($peer):?><header><div class="avatar"><?=e(strtoupper(substr($peer['name'],0,1)))?></div><div><strong><?=e($peer['name'])?></strong><small><?=e(ucfirst($peer['role']))?></small></div></header><div class="message-list" id="messageList"><?php foreach($messages as $message):?><article class="message <?=$message['sender_id']===$me?'mine':'theirs'?>"><div><?=nl2br(e($message['body']))?></div><small><?=e(substr($message['created_at'],11,5))?></small></article><?php endforeach;?><?php if(!$messages):?><div class="empty"><?=__('Belum ada pesan. Sapa terlebih dahulu.','No messages yet. Say hello.')?></div><?php endif;?></div><form class="chat-compose" method="post" action="/chat/send"><?=Csrf::field()?><input type="hidden" name="recipient_id" value="<?=$peer['id']?>"><textarea name="body" rows="2" maxlength="2000" required placeholder="<?=__('Tulis pesan...','Write a message...')?>"></textarea><button class="btn primary"><?=__('Kirim','Send')?></button></form><?php else:?><div class="chat-empty"><span><?=nav_icon('chat')?></span><h2><?=__('Percakapan internal SIMIT','SIMIT internal chat')?></h2><p><?=__('Pilih pengguna di sebelah kiri untuk mengirim pesan.','Select a user on the left to send a message.')?></p></div><?php endif;?></section></div><script>const box=document.getElementById('messageList');if(box)box.scrollTop=box.scrollHeight;</script>
